SELECT GROUPING_ID(f.anio,f.mes,p.order_status) AS nivel,f.anio,f.mes,p.order_status,COUNT_BIG(*) AS pedidos,COUNT_BIG(p.payment_value_total) AS con_pago,COUNT_BIG(*)-COUNT_BIG(p.payment_value_total) AS sin_pago,SUM(p.payment_value_total) AS importe_observado FROM dw.FactPedidos p JOIN dw.DimFecha f ON f.fecha_key=p.fecha_compra_key WHERE p.fecha_compra_key <> -1 AND f.fecha >= CAST(@Desde AS date) AND f.fecha <= CAST(@Hasta AS date) AND CAST(@Desde AS date) <= CAST(@Hasta AS date) AND (@EstadoPedido = '__TODOS__' OR (@EstadoPedido = '__DESCONOCIDO__' AND p.order_status IS NULL) OR p.order_status = @EstadoPedido) GROUP BY GROUPING SETS ((f.anio,f.mes,p.order_status),(f.anio,f.mes),()) HAVING COUNT_BIG(*) > 0 ORDER BY nivel,f.anio,f.mes,p.order_status;
